<script>
document.addEventListener('DOMContentLoaded',()=>{
  const areaModal=document.getElementById('areaModal');
  areaModal?.addEventListener('show.bs.modal',event=>{const b=event.relatedTarget;let d={};if(b?.classList.contains('js-edit-area')){try{d=JSON.parse(b.dataset.json||'{}')}catch(e){d={}}}document.getElementById('areaModalTitle').textContent=d.id?'Editar área':'Nueva área';const map={areaId:'id',areaCode:'code',areaName:'name',areaScope:'scope_type',areaUsage:'usage_type',areaProperty:'property_id',areaCapacity:'capacity',areaOpening:'opening_time',areaClosing:'closing_time',areaRate:'base_rate',areaDeposit:'security_deposit',areaMin:'minimum_minutes',areaMax:'maximum_minutes',areaAdvance:'advance_days',areaCancel:'cancellation_hours',areaRules:'rules_text',areaStatus:'status'};Object.entries(map).forEach(([el,key])=>{document.getElementById(el).value=d[key]??(el==='areaScope'?'common':el==='areaUsage'?'general':el==='areaStatus'?'active':el==='areaRate'||el==='areaDeposit'?'0':el==='areaMin'?'60':el==='areaAdvance'?'90':el==='areaCancel'?'24':'');});document.getElementById('areaReservable').checked=Number(d.is_reservable||0)===1;document.getElementById('areaSecurity').checked=Number(d.is_security_zone||0)===1;document.getElementById('areaApproval').checked=d.id?Number(d.requires_approval||0)===1:true;});
  <?php if($presetNew):?>setTimeout(()=>{const m=document.getElementById('areaModal');if(m){document.getElementById('areaProperty').value='<?=$presetPropertyId?>';bootstrap.Modal.getOrCreateInstance(m).show();}},50);<?php endif;?>
  const checks=[...document.querySelectorAll('.js-area-select')],selectAll=document.getElementById('selectAllAreas'),toolbar=document.getElementById('areaBulkToolbar'),badge=document.getElementById('areaBulkCount'),modalEl=document.getElementById('areaBulkModal'),modal=modalEl?new bootstrap.Modal(modalEl):null,form=document.getElementById('areaBulkForm'),submit=document.getElementById('areaBulkSubmit'),status=document.getElementById('areaBulkStatus');
  const selected=()=>checks.filter(c=>c.checked).map(c=>c.value);const update=()=>{const ids=selected();if(toolbar)toolbar.hidden=!ids.length;if(badge)badge.textContent=`${ids.length} seleccionada${ids.length===1?'':'s'}`;if(selectAll){selectAll.checked=checks.length>0&&ids.length===checks.length;selectAll.indeterminate=ids.length>0&&ids.length<checks.length;}};checks.forEach(c=>c.addEventListener('change',update));selectAll?.addEventListener('change',()=>{checks.forEach(c=>c.checked=selectAll.checked);update();});document.getElementById('areaBulkClear')?.addEventListener('click',()=>{checks.forEach(c=>c.checked=false);update();});
  const titles={move:'Mover áreas',scope:'Cambiar ámbito',usage:'Cambiar uso / función',status:'Cambiar estado',duplicate:'Duplicar áreas',delete:'Eliminar áreas'};const helps={move:'Cambia DÓNDE está el área sin cambiar QUÉ es.',scope:'Cambia su naturaleza: común, privado, técnico, servicio, restringido o público.',usage:'Cambia para qué sirve: lobby, circulación, estacionamiento, etc.',status:'Cambia el estado de todas las seleccionadas.',duplicate:'Crea copias independientes.',delete:'Conserva historial desactivando áreas con dependencias.'};
  const openBulk=(action,forcedIds=null)=>{const ids=forcedIds||selected();if(!ids.length)return;document.getElementById('areaBulkAction').value=action;document.getElementById('areaBulkTitle').textContent=titles[action]||'Acción masiva';document.getElementById('areaBulkModalCount').textContent=`${ids.length} área${ids.length===1?'':'s'} seleccionada${ids.length===1?'':'s'}`;document.getElementById('areaBulkHelp').textContent=helps[action]||'';document.querySelectorAll('.js-area-section').forEach(section=>{const active=section.dataset.section===action;section.hidden=!active;section.querySelectorAll('input,select,textarea').forEach(control=>control.disabled=!active);});const holder=document.getElementById('areaBulkIds');holder.innerHTML='';ids.forEach(id=>{const input=document.createElement('input');input.type='hidden';input.name='selected_ids[]';input.value=id;holder.appendChild(input);});document.getElementById('areaConfirmDelete').checked=false;submit.className=action==='delete'?'btn btn-danger':'btn btn-primary';submit.textContent=action==='delete'?'Eliminar o desactivar':'Aplicar acción';status.textContent='';modal?.show();};
  document.querySelectorAll('.js-area-bulk').forEach(b=>b.addEventListener('click',()=>openBulk(b.dataset.action||'')));document.querySelectorAll('.js-duplicate-one-area').forEach(b=>b.addEventListener('click',()=>openBulk('duplicate',[b.dataset.areaId])));form?.addEventListener('submit',event=>{const action=document.getElementById('areaBulkAction').value;if(action==='delete'&&!document.getElementById('areaConfirmDelete').checked){event.preventDefault();status.textContent='Debes confirmar la eliminación.';return;}submit.disabled=true;submit.innerHTML='<span class="spinner-border spinner-border-sm me-2"></span>Procesando…';});update();
});
</script>
<?php endif;?>
